"""Slate rules for the job lane: cap, charters, dated steps, checkpoints.

Design: docs/superpowers/specs/2026-09-14-prioritization-system-design.md

Every earlier prioritization fix died because it needed remembering. This
module only *evaluates* the rules; KeystoneOS/scripts/ritual-check.ps1 calls
`portfolio.py slate-check --json` on a timer and raises the desktop prompt.
It never writes the registry.
"""

from __future__ import annotations

import datetime as _dt

PILLARS = {"data", "education", "research"}
STEP_COUNT = 4
_RANK = {"OK": 0, "DUE": 1, "OVERDUE": 2}


def parse_date(value) -> _dt.date | None:
    if not isinstance(value, str):
        return None
    try:
        return _dt.date.fromisoformat(value)
    except ValueError:
        return None


def charter_gaps(charter, semester_close: _dt.date | None) -> list[str]:
    """What stops this charter from being complete. Empty list = complete."""
    if not isinstance(charter, dict):
        return ["no charter"]
    gaps = []
    if charter.get("pillar") not in PILLARS:
        gaps.append(f"pillar must be one of {sorted(PILLARS)}")
    for field in ("jd_duty", "receiver", "done_means"):
        if not str(charter.get(field) or "").strip():
            gaps.append(f"no {field}")
    finish = parse_date(charter.get("finish_by"))
    if finish is None:
        gaps.append("no finish_by date")
    elif semester_close and finish > semester_close:
        gaps.append(f"finish_by {finish} is after semester close {semester_close}")
    steps = charter.get("steps")
    if not isinstance(steps, list) or len(steps) != STEP_COUNT:
        gaps.append(f"needs exactly {STEP_COUNT} steps")
    else:
        for s in steps:
            if not str(s.get("name") or "").strip() or parse_date(s.get("due")) is None:
                gaps.append("every step needs a name and a due date")
                break
    return gaps


def check(data: dict, today: _dt.date) -> dict:
    cfg = (data.get("meta") or {}).get("slate")
    if not isinstance(cfg, dict) or cfg.get("retired"):
        # meta.slate.retired: Eric retired the slate 2026-10-30; nothing is checked or prompted
        return {"status": "OK", "enabled": False, "active": 0, "cap": None, "problems": []}

    cap = cfg.get("cap")
    close = parse_date(cfg.get("semester_close"))
    problems: list[dict] = []

    def add(level, project, message):
        problems.append({"level": level, "project": project, "message": message})

    active = [p for p in data.get("projects", [])
              if p.get("lane") == "job" and p.get("status") == "active"]

    if isinstance(cap, int) and len(active) > cap:
        add("OVERDUE", "(slate)",
            f"{len(active)} active job projects, cap is {cap} - finish or park one before anything else")

    for p in active:
        name = p.get("name", "<unnamed>")
        c = p.get("charter")
        gaps = charter_gaps(c, close)
        if gaps:
            add("DUE", name, "charter incomplete: " + "; ".join(gaps))
        if not isinstance(c, dict):
            continue
        finish = parse_date(c.get("finish_by"))
        if finish and finish < today:
            add("OVERDUE", name, f"past its finish date {finish} and still active - deliver, re-date with the receiver, or drop")
            continue
        for s in c.get("steps") or []:
            due = parse_date(s.get("due"))
            if due and due < today and not s.get("done"):
                add("OVERDUE", name,
                    f"step '{s.get('name')}' was due {due} - receiver: {c.get('receiver') or 'none named'}")
                break  # the earliest late step is the one to act on

    for cp in cfg.get("checkpoints") or []:
        due = parse_date(cp.get("due"))
        if due and due < today and not cp.get("done") and not cp.get("skipped"):
            add("OVERDUE", "(checkpoint)", f"{cp.get('name')} was due {due}")

    next_up = cfg.get("next_up") or []
    if isinstance(cap, int) and next_up and len(active) < cap:
        add("DUE", next_up[0],
            f"a slot is open ({len(active)} of {cap}) - write its charter and start it")

    import seven_day  # lazy: tests copy portfolio.py alone into scratch dirs
    problems.extend(seven_day.check(data, today))

    status = max((p["level"] for p in problems), key=_RANK.get, default="OK")
    return {"status": status, "enabled": True, "active": len(active), "cap": cap, "problems": problems}


def format_report(result: dict) -> str:
    if not result["enabled"]:
        return "slate: not configured (meta.slate missing)"
    lines = [f"slate: {result['status']} - {result['active']} of {result['cap']} active"]
    for p in result["problems"]:
        lines.append(f"  {p['level']:<8} {p['project']}: {p['message']}")
    return "\n".join(lines)


def _in_window(value, start: _dt.date, end: _dt.date) -> bool:
    d = parse_date(value)
    return d is not None and start <= d <= end


def _checkpoint_state(cp: dict) -> str:
    if cp.get("done"):
        return f"done {cp['done']}"
    if cp.get("skipped"):
        return f"SKIPPED {cp['skipped'].get('date')} ({cp['skipped'].get('reason')})"
    return "NOT DONE"


def week_report(data: dict, end: _dt.date) -> str:
    """Markdown summary of the 7 days ending `end`, for Eric's own weekly review.

    Written by the Friday ritual run into the vault. Blocks are updates whose
    note starts with "[block]" - interview-me logs them that way.
    """
    start = end - _dt.timedelta(days=6)
    lines = [f"# Weekly slate - week ending {end}", f"Window: {start} to {end}", ""]
    cfg = (data.get("meta") or {}).get("slate")
    if not isinstance(cfg, dict):
        lines.append("Slate not configured (meta.slate missing).")
        return "\n".join(lines) + "\n"

    result = check(data, end)
    lines += [f"**Slate:** {result['status']} - {result['active']} of {result['cap']} active", ""]
    active = sorted((p for p in data.get("projects", [])
                     if p.get("lane") == "job" and p.get("status") == "active"),
                    key=lambda p: p.get("rank", 0))
    for p in active:
        c = p.get("charter") or {}
        updates = sorted((u for u in p.get("updates") or [] if _in_window(u.get("date"), start, end)),
                         key=lambda u: u["date"])
        blocks = [u for u in updates if str(u.get("note", "")).startswith("[block]")]
        lines += [f"## {p['name']} - {c.get('receiver') or 'no receiver'}", "",
                  f"- Blocks logged: {len(blocks)}"]
        if updates:
            lines.append("- Moved:")
            lines += [f"  - {u['date']}: {u['note']}" for u in updates]
        else:
            lines.append("- No movement logged this week.")
        steps = c.get("steps") or []
        done = [s for s in steps if _in_window(s.get("done"), start, end)]
        if done:
            lines.append("- Steps done: " + "; ".join(s["name"] for s in done))
        # Same rule as check(): due today is not late yet.
        late = [s for s in steps if not s.get("done") and (parse_date(s.get("due")) or end) < end]
        for s in late:
            lines.append(f"- LATE: {s['name']} was due {s['due']}")
        nxt = next((s for s in steps if not s.get("done")), None)
        lines.append(f"- Next step: {nxt['name']} due {nxt['due']}" if nxt else "- Next step: all steps done")
        lines.append("")

    cps = [cp for cp in cfg.get("checkpoints") or [] if _in_window(cp.get("due"), start, end)]
    lines += ["## Checkpoints", ""]
    if cps:
        lines += [f"- {cp['name']} (due {cp['due']}): " + _checkpoint_state(cp) for cp in cps]
    else:
        lines.append("- None due this week.")
    lines.append("")
    if cfg.get("next_up"):
        lines += [f"**Next up:** {', '.join(cfg['next_up'])}", ""]
    return "\n".join(lines)

