import json, subprocess, sys
def get(fid):
    out = subprocess.run(["gws","drive","files","get","--params",json.dumps({"fileId":fid,"fields":"id,name,parents"})],capture_output=True,text=True).stdout
    return json.loads(out[out.index("{"):])
def kids(fid):
    out = subprocess.run(["gws","drive","files","list","--params",json.dumps({"q":f"\"{fid}\" in parents and trashed=false","fields":"files(name,modifiedTime)","pageSize":50,"orderBy":"modifiedTime desc"})],capture_output=True,text=True).stdout
    return json.loads(out[out.index("{"):]).get("files",[])
for fid in sys.argv[1:]:
